def solve() -> None:
    data = sys.stdin.read().split()
    if not data:
        return
    n = int(data[0])
    a = [int(x) for x in data[1:1 + n]]

    vals = sorted(set(a))
    m = len(vals)
    c = [bisect.bisect_left(vals, x) + 1 for x in a]

    bit_l = [0] * (m + 1)
    left_less = [0] * n
    for j in range(n):
        cj = c[j]
        s = 0
        i = cj - 1
        while i > 0:
            s += bit_l[i]
            i -= i & -i
        left_less[j] = s
        i = cj
        while i <= m:
            bit_l[i] += 1
            i += i & -i

    bit_r = [0] * (m + 1)
    ans = 0
    for j in range(n - 1, -1, -1):
        cj = c[j]
        s = 0
        i = cj
        while i > 0:
            s += bit_r[i]
            i -= i & -i
        right_greater = (n - 1 - j) - s
        ans += left_less[j] * right_greater
        i = cj
        while i <= m:
            bit_r[i] += 1
            i += i & -i

    sys.stdout.write(f"{ans}\n")


