import sys


def solve() -> None:
    data = sys.stdin.read().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    q = int(next(it))

    sz = 1
    while sz < n:
        sz <<= 1
    h = sz.bit_length() - 1

    tree = [0] * (2 * sz)
    lazy = [0] * sz
    seg_len = [0] * (2 * sz)
    for p in range(1, 2 * sz):
        seg_len[p] = sz >> (p.bit_length() - 1)

    for i in range(n):
        tree[sz + i] = int(next(it))
    for i in range(sz - 1, 0, -1):
        tree[i] = tree[i << 1] + tree[i << 1 | 1]

    def push_path(p: int) -> None:
        for s in range(h, 0, -1):
            i = p >> s
            v = lazy[i]
            if v:
                lazy[i] = 0
                lc = i << 1
                rc = lc | 1
                clen = seg_len[lc]
                add_val = v * clen
                tree[lc] += add_val
                tree[rc] += add_val
                if lc < sz:
                    lazy[lc] += v
                    lazy[rc] += v

    def pull_path(p: int) -> None:
        p >>= 1
        while p:
            tree[p] = tree[p << 1] + tree[p << 1 | 1] + lazy[p] * seg_len[p]
            p >>= 1

    out = []
    for _ in range(q):
        t = int(next(it))
        if t == 1:
            l0 = int(next(it)) - 1 + sz
            r0 = int(next(it)) + sz
            v = int(next(it))
            push_path(l0)
            push_path(r0 - 1)
            l, r = l0, r0
            while l < r:
                if l & 1:
                    tree[l] += v * seg_len[l]
                    if l < sz:
                        lazy[l] += v
                    l += 1
                if r & 1:
                    r -= 1
                    tree[r] += v * seg_len[r]
                    if r < sz:
                        lazy[r] += v
                l >>= 1
                r >>= 1
            pull_path(l0)
            pull_path(r0 - 1)
        else:
            l = int(next(it)) - 1 + sz
            r = int(next(it)) + sz
            push_path(l)
            push_path(r - 1)
            res = 0
            while l < r:
                if l & 1:
                    res += tree[l]
                    l += 1
                if r & 1:
                    r -= 1
                    res += tree[r]
                l >>= 1
                r >>= 1
            out.append(str(res))

    sys.stdout.write("\n".join(out) + "\n")


