                tree[rc] = v
                if lc < sz:
                    has_lazy[lc] = 1
                    has_lazy[rc] = 1
                    lazy[lc] = v
                    lazy[rc] = v

    def pull_path(p: int) -> None:
        p >>= 1
        while p:
